#!/usr/bin/env node
/**
 * Prepares precomputedAtmosphereTables.ts under dated build/generated by default: the two tables that
 * createAtmosphere() spends most of its time on, light scattered more than once and the sky's light on level
 * ground, for the settings' default atmosphere, as this checkout's src/atmosphere.ts builds them when it has
 * none. A page's sky then starts without building them; other parameters still do.
 *
 *   node scripts/sky/build-atmosphere-tables.mjs src/precomputedAtmosphereTables.ts
 *
 * replaces the committed module. src/precomputedAtmosphereTables.test.ts fails when they are no longer the
 * settings' defaults or, bit for bit, what src/atmosphere.ts builds; then run this again.
 */
import { writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { build } from "vite";
import { outputFile } from "../outputDirectory.mjs";

const root = fileURLToPath(new URL("../../", import.meta.url));
const ENTRY = "\0atmosphere-tables-entry";
const NONE = "\0no-precomputed-atmosphere-tables";

// The model and the settings from source, bundled in memory, with no precomputed tables to start from.
const bundled = await build({
  configFile: false, root, logLevel: "warn", publicDir: false,
  plugins: [{
    name: "atmosphere-without-precomputed-tables", enforce: "pre",
    resolveId: id => (id === ENTRY ? ENTRY : id === "./precomputedAtmosphereTables.js" ? NONE : null),
    load: id => (id === ENTRY
      ? `export { createAtmosphere } from ${JSON.stringify(`${root}src/atmosphere.ts`)};\nexport { SKY_PARAMETERS } from ${JSON.stringify(`${root}src/settings.ts`)};`
      : id === NONE ? "export const PRECOMPUTED_ATMOSPHERE_TABLES = [];" : null),
  }],
  build: { write: false, minify: false, rolldownOptions: { input: ENTRY, preserveEntrySignatures: "strict" } },
});
const [chunk] = (Array.isArray(bundled) ? bundled[0] : bundled).output;
const { createAtmosphere, SKY_PARAMETERS } = await import(`data:text/javascript;base64,${Buffer.from(chunk.code).toString("base64")}`);

const setting = id => SKY_PARAMETERS.find(parameter => parameter.id === id).default;
const parameters = { aerosolOpticalDepth: setting("sky.atmosphere.aerosolOpticalDepth"), groundAlbedo: setting("sky.atmosphere.groundAlbedo") };
// A numeric kernel is handed copies of the tables its atmosphere was built with. None is started.
let tables;
createAtmosphere(parameters, undefined, {
  execution: "worker",
  createKernel(snapshot) { tables = snapshot; throw new Error("Only the tables are wanted."); },
});

const lines = table => {
  const view = new DataView(new ArrayBuffer(table.length * 4));
  table.forEach((value, index) => view.setFloat32(index * 4, value, true));
  return Buffer.from(view.buffer).toString("base64").match(/.{1,120}/g).map(line => `      "${line}",`).join("\n");
};
const target = outputFile("precomputedAtmosphereTables.ts", process.argv[2]);
writeFileSync(target, `/**
 * Generated by scripts/sky/build-atmosphere-tables.mjs. Do not edit.
 *
 * Two of the tables createAtmosphere() builds, for the settings' default atmosphere, as src/atmosphere.ts
 * builds them: light scattered more than once, by the Sun's height and the height above the ground, and the
 * sky's light on level ground, by the Sun's height. Three bands a sample, as their natural logarithms, in
 * little-endian float32s.
 */

export interface PrecomputedAtmosphereTables {
  aerosolOpticalDepth: number;
  groundAlbedo: number;
  /** ${tables.multipleScattering.length / 3} samples, base64. */
  multipleScattering: string;
  /** ${tables.groundIrradiance.length / 3} samples, base64. */
  groundIrradiance: string;
}

export const PRECOMPUTED_ATMOSPHERE_TABLES: readonly PrecomputedAtmosphereTables[] = [
  {
    aerosolOpticalDepth: ${tables.aerosolOpticalDepth},
    groundAlbedo: ${tables.groundAlbedo},
    multipleScattering: [
${lines(tables.multipleScattering)}
    ].join(""),
    groundIrradiance: [
${lines(tables.groundIrradiance)}
    ].join(""),
  },
];
`);
console.log(`Aerosol optical depth ${tables.aerosolOpticalDepth}, ground albedo ${tables.groundAlbedo}: ${tables.multipleScattering.length + tables.groundIrradiance.length} float32s, written to ${target}`);
